import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 9

    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False,
    )

    records = []
    for record in reader:
        if record:
            record[0] = record[0].lstrip("\ufeff")
        records.append(record)

    def is_empty(record):
        return not record or all(value == "" for value in record)

    def looks_like_data(record):
        if len(record) < 2:
            return False
        first = record[0].strip()
        second = record[1].strip()
        date_like = bool(re.match(r"^\d{1,4}[-/]\d{1,2}[-/]\d{1,4}$", first))
        time_like = bool(re.match(r"^\d{1,2}:\d{2}(?::\d{2})?$", second))
        return date_like and time_like

    def is_preamble(record):
        if not record:
            return True
        if len(record) == 1:
            value = record[0].strip().lower()
            if value.startswith("sep="):
                return True
        return False

    header_index = None

    for index, record in enumerate(records):
        if is_empty(record) or is_preamble(record):
            continue
        if len(record) == expected_width and not looks_like_data(record):
            header_index = index
            break

    if header_index is None:
        for index, record in enumerate(records):
            if is_empty(record) or is_preamble(record):
                continue
            if not looks_like_data(record) and len(record) > 1:
                header_index = index
                break

    if header_index is None:
        for index, record in enumerate(records):
            if not is_empty(record) and not is_preamble(record):
                header_index = index
                break

    if header_index is None:
        return {"columns": ["" for _ in range(expected_width)], "rows": []}

    def normalize(record):
        values = list(record)
        if len(values) < expected_width:
            values.extend([""] * (expected_width - len(values)))
        elif len(values) > expected_width:
            values = values[:expected_width - 1] + [",".join(values[expected_width - 1:])]
        return values

    columns = normalize(records[header_index])
    rows = [
        normalize(record)
        for record in records[header_index + 1:]
        if not is_empty(record)
    ]

    return {"columns": columns, "rows": rows}
